import React from "react";
import "./Booking.css";

function Booking() {
  return (
    <div className="booking-page">

      <h1>Book Your Bus Ticket</h1>

      <p>
        Select your route and complete your booking.
      </p>

    </div>
  );
}

export default Booking;
